    [NSLayoutConstraint activateConstraints:@[[self.playerController.view.leadingAnchor constraintEqualToAnchor:video.leadingAnchor],[self.playerController.view.trailingAnchor constraintEqualToAnchor:video.trailingAnchor],[self.playerController.view.topAnchor constraintEqualToAnchor:video.topAnchor],[self.playerController.view.bottomAnchor constraintEqualToAnchor:video.bottomAnchor]]];
