- (void)dealloc {if(self.observedItem){@try{[self.observedItem removeObserver:self forKeyPath:@"status" context:CCTVPlayerItemStatusContext];}@catch(NSException *exception){}}if(self.observingPlayer){@try{[self.player removeObserver:self forKeyPath:@"timeControlStatus" context:CCTVPlayerTimeControlContext];}@catch(NSException *exception){}}[self.client cancel];[self.player pause];}
- (void)buildLines {for(UIView *v in self.lineButtons.arrangedSubviews.copy){[self.lineButtons removeArrangedSubview:v];[v removeFromSuperview];}NSArray *lines=self.lines;for(NSUInteger idx=0;idx<lines.count;idx++){NSDictionary *line=lines[idx];UIButton *button=[UIButton buttonWithType:UIButtonTypeSystem];[button setTitle:line[@"name"]?:[NSString stringWithFormat:@"线路 %lu",(unsigned long)idx+1] forState:UIControlStateNormal];button.titleLabel.font=[UIFont systemFontOfSize:13 weight:UIFontWeightMedium];HostStylePillButton(button,idx==self.lineIndex);button.tag=idx;[button addTarget:self action:@selector(selectLine:) forControlEvents:UIControlEventTouchUpInside];[self.lineButtons addArrangedSubview:button];}}
- (void)playResult:(NSDictionary *)result {NSString *raw=[result[@"url"] isKindOfClass:NSString.class]?result[@"url"]:@"";NSURL *url=[NSURL URLWithString:raw];if(!url||![@[@"http",@"https"] containsObject:url.scheme.lowercaseString]||!url.host.length){self.status.text=@"资源未返回有效的 HTTP/HTTPS 播放地址";return;}NSURL *sourceURL=[NSURL URLWithString:[result[@"originalURL"] isKindOfClass:NSString.class]?result[@"originalURL"]:raw];NSString *extension=sourceURL.pathExtension.lowercaseString?:@"";NSSet *direct=[NSSet setWithArray:@[@"m3u8",@"m3u",@"mp4",@"m4v",@"mov",@"m4a",@"mp3"]];if([result[@"parse"] integerValue]>0 && ![direct containsObject:extension]){[self.player pause];MediaWebViewController *web=[[MediaWebViewController alloc] initWithResult:result title:self.title];UINavigationController *nav=[[UINavigationController alloc] initWithRootViewController:web];[self presentViewController:nav animated:YES completion:nil];return;}self.result=result;self.status.text=@"已提交播放器 · 等待播放状态";AVPlayerItem *item=[AVPlayerItem playerItemWithURL:url];if(self.observedItem){@try{[self.observedItem removeObserver:self forKeyPath:@"status" context:CCTVPlayerItemStatusContext];}@catch(NSException *exception){}self.observedItem=nil;}if(self.player.currentItem)[NSNotificationCenter.defaultCenter removeObserver:self name:AVPlayerItemFailedToPlayToEndTimeNotification object:self.player.currentItem];[NSNotificationCenter.defaultCenter addObserver:self selector:@selector(playerItemFailed:) name:AVPlayerItemFailedToPlayToEndTimeNotification object:item];if(!self.player){self.player=[AVPlayer playerWithPlayerItem:item];[self.player addObserver:self forKeyPath:@"timeControlStatus" options:NSKeyValueObservingOptionInitial|NSKeyValueObservingOptionNew context:CCTVPlayerTimeControlContext];self.observingPlayer=YES;}else[self.player replaceCurrentItemWithPlayerItem:item];self.observedItem=item;[item addObserver:self forKeyPath:@"status" options:NSKeyValueObservingOptionInitial|NSKeyValueObservingOptionNe