- (void)observeValueForKeyPath:(NSString *)keyPath ofObject:(id)object change:(NSDictionary<NSKeyValueChangeKey,id> *)change context:(void *)context {if(context==CCTVPlayerItemStatusContext){AVPlayerItem *item=(AVPlayerItem *)object;if(item.status==AVPlayerItemStatusFailed){dispatch_async(dispatch_get_main_queue(),^{if(item!=self.player.currentItem)return;self.status.text=[NSString stringWithFormat:@"媒体载入失败 · %@",item.error.localizedDescription?:@"来源无法读取，请尝试其他线路"];self.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc] initWithTitle:@"重试" style:UIBarButtonItemStylePlain target:self action:@selector(retryCurrentEpisode)];});}else if(item.status==AVPlayerItemStatusReadyToPlay){dispatch_async(dispatch_get_main_queue(),^{if(item==self.player.currentItem&&self.player.timeControlStatus==AVPlayerTimeControlStatusPaused)self.status.text=@"媒体已准备 · 等待播放状态；首帧渲染未知";});}return;}if(context==CCTVPlayerTimeControlContext){AVPlayerTimeControlStatus state=self.player.timeControlStatus;dispatch_async(dispatch_get_main_queue(),^{if(state==AVPlayerTimeControlStatusPlaying)self.status.text=@"AVPlayer 报告播放中 · 首帧渲染状态未知";else if(state==AVPlayerTimeControlStatusWaitingToPlayAtSpecifiedRate)self.status.text=@"正在缓冲 · 等待 AVPlayer 开始播放";else if(self.player.currentItem.status==AVPlayerItemStatusReadyToPlay)self.status.text=@"媒体已准备 · 当前暂停；首帧渲染未知";});return;}[super observeValueForKeyPath:keyPath ofObject:object change:change context:context];}
- (void)playerItemFailed:(NSNotification *)notification {if(notification.object!=self.player.currentItem)return;NSError *error=notification.userInfo[AVPlayerItemFailedToPlayToEndTimeErrorKey];self.status.text=[NSString stringWithFormat:@"播放失败 · %@",error.localizedDescription?:@"播放器未能打开此媒体"];self.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc] initWithTitle:@"重试" style:UIBarButtonItemStylePlain target:self action:@selector(retryCurrentEpisode)];}
- (void)retryCurrentEpisode {[self resolveAndPlay];}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)tableView {return 1;}
- (NSInteger)tableView:(UITableView *)tableView numberOfRowsInSection:(NSInteger)section {return self.episodes.count;}
- (NSString *)tableView:(UITableView *)tableView titleForHeaderInSection:(NSInteger)section {return self.episodes.count?[NSString stringWithFormat:@"%@ · %lu 集",self.lines[self.lineIndex][@"name"]?:@"选集",(unsigned long)self.episodes.count]:@"此来源没有提供分集";}
- (UITableViewCell *)tableView:(UITableView *)tableView cellForRowAtIndexPath:(NSIndexPath *)ip {UITableViewCell *cell=[[UITableViewCell alloc] initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:nil];cell.backgroundColor=HostCard();NSDictionary *episode=self.episodes[ip.row];cell.textLabel.text=episode[@"name"]?:[NSString stringWithFormat:@"第 %ld 集",(long)ip.row+1];cell.textLabel.textColor=ip.row==self.episodeIndex?HostAccent():UIColor.labelColor;cell.detailTextLabel.text=ip.row==self.episodeIndex?@"当前播放":@"点击播放";cell.detailTextLabel.textColor=UIColor.secondaryLabelColor;cell.accessoryType=ip.row==self.episodeIndex?UITableViewCellAccessoryCheckmark:UITableViewCellAccessoryDisclosureIndicator;return cell;}
