- (void)tableView:(UITableView *)tableView didSelectRowAtIndexPath:(NSIndexPath *)ip {[tableView deselectRowAtIndexPath:ip animated:YES];if(ip.row>=self.episodes.count)return;if(ip.row==self.episodeIndex)return;self.episodeIndex=ip.row;[self.table reloadData];[self resolveAndPlay];}
- (void)resolveAndPlay {NSArray *lines=self.lines,*episodes=self.episodes;if(self.lineIndex>=lines.count||self.episodeIndex>=episodes.count)return;NSDictionary *line=lines[self.lineIndex],*episode=episodes[self.episodeIndex];self.resolving=YES;NSUInteger gen=++self.generation;[self.spinner startAnimating];self.status.text=[NSString stringWithFormat:@"正在解析 %@…",episode[@"name"]?:@"当前分集"];NSDictionary *source=self.context[@"source"]?:@{};NSDictionary *args=@{@"id":episode[@"id"]?:@"",@"lineId":line[@"id"]?:@""};NSString *provider=self.context[@"provider"];if(provider.length){NSMutableDictionary *m=[args mutableCopy];m[@"provider"]=provider;args=m;}
